;background:#061923;cursor:grab;transition:opacity .15s,border-color .15s}.nav-item.dragging{opacity:.45;border-color:#43d1ef}.drag-handle{color:#5e8290}.nav-item strong{font-size:10px;color:#dceef2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nav-item small{font-size:8px;color:#587784;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nav-item a{width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--line);border-radius:9px;color:#8bb0bd;text-decoration:none}.nav-empty{padding:18px;text-align:center;color:#6e8d98;font-size:10px;border:1px dashed rgba(255,255,255,.08);border-radius:10px}.table-card{border:1px solid var(--line);border-radius:17px;overflow:hidden;background:rgba(255,255,255,.02)}.table-head,.row{display:grid;grid-template-columns:2fr .7fr .8fr .55fr;gap:12px;align-items:center;padding:13px 15px}.table-head{color:#5f8290;font-size:9px;text-transform:uppercase;border-bottom:1px solid var(--line)}.row{border-bottom:1px solid rgba(255,255,255,.045);font-size:10px}.row:last-child{border:0}.row strong{display:block;color:#d9edf2}.row small{display:block;color:#587784;margin-top:4px}.date{font-size:9px;color:#71919c}.status{font-size:8px;text-transform:uppercase;padding:5px 7px;border-radius:999px;width:max-content}.published{background:rgba(32,212,170,.1);color:#72e5c9}.draft{background:rgba(255,190,70,.08);color:#e6c37c}.actions{display:flex;gap:7px}.actions a,.actions button{width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--line);background:transparent;color:#8bb0bd;border-radius:9px;text-decoration:none}.actions form{margin:0}.notice{padding:11px 13px;margin-bottom:12px;border-radius:11px;background:rgba(67,194,137,.1);color:#a8e5ca;font-size:10px}.empty{min-height:220px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;color:#6f909d}.empty i{font-size:30px}.empty strong{color:#9dbac3}.empty span{font-size:10px}@media(max-width:650px){.hero{align-items:flex-start;flex-direction:column}.primary{width:100%;justify-content:center}.workspace{grid-template-columns:1fr}.nav-manager-head{align-items:flex-start;flex-direction:column}.nav-item{grid-template-columns:25px minmax(0,1fr) 32px}.nav-item small{display:none}.table-head{display:none}.row{grid-template-columns:1fr auto}.actions{grid-column:2;grid-row:1/3}}</style>@endpush
