@push('scripts')<script>const navList=document.getElementById('navigation-sortable');if(navList){let dragged=null;const status=document.getElementById('nav-save-status');const csrf=document.querySelector('meta[name="csrf-token"]')?.content;navList.querySelectorAll('.nav-item').forEach(item=>{item.addEventListener('dragstart',e=>{dragged=item;item.classList.add('dragging');e.dataTransfer.effectAllowed='move'});item.addEventListener('dragend',async()=>{item.classList.remove('dragging');const ids=[...navList.querySelectorAll('.nav-item')].map(el=>el.dataset.id);status.textContent='Saving...';status.style.color='#e6c37c';try{const res=await fetch('{{ route('admin.site-content.navigation.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({ids})});if(!res.ok)throw new Error();status.textContent='Saved';status.style.color='#71dfc5'}catch(e){status.textContent='Could not save';status.style.color='#ff9d9d'}});item.addEventListener('dragover',e=>{e.preventDefault();if(!dragged||dragged===item)return;const rect=item.getBoundingClientRect();if(e.clientY>rect.top+rect.height/2)item.after(dragged);else item.before(dragged)})})}</script>@endpush
